	// clears it, but we need the original list for carry-forward computation.
	// For mid-session commits (ACTIVE, no shadow branch), state.FilesTouched may be empty
	// because no SaveStep/Stop has been called yet. Extract files from transcript.
	filesTouchedBefore := make([]string, len(state.FilesTouched))
	copy(filesTouchedBefore, state.FilesTouched)
	if len(filesTouchedBefore) == 0 && state.Phase.IsActive() && state.TranscriptPath != "" {
		filesTouchedBefore = s.extractFilesFromLiveTranscript(ctx, state)
	}

	logging.Debug(logCtx, "post-commit: carry-forward prep",
		slog.String("session_id", state.SessionID),
		slog.Bool("is_active", state.Phase.IsActive()),
		slog.String("transcript_path", state.TranscriptPath),
		slog.Int("files_touched_before", len(filesTouchedBefore)),
		slog.Any("files", filesTouchedBefore),
	)

	// Run the state machine transition with handler for strategy-specific actions.
	handler := &postCommitActionHandler{
		s:                      s,
		ctx:                    ctx,
		repo:                   repo,
		checkpointID:           checkpointID,
		head:                   head,
		commit:                 commit,
		newHead:                newHead,
		shadowBranchName:       shadowBranchName,
		shadowBranchesToDelete: shadowBranchesToDelete,
		committedFileSet:       committedFileSet,
		hasNew:                 hasNew,
		filesTouchedBefore:     filesTouchedBefore,
		headTree:               headTree,
		parentTree:             parentTree,
		shadowRef:              shadowRef,
		shadowTree:             shadowTree,
	}

	if err := TransitionAndLog(ctx, state, session.EventGitCommit, *transitionCtx, handler); err != nil {
		logging.Warn(logCtx, "post-commit action handler error",
			slog.String("error", err.Error()))
	}

	// Record checkpoint ID for ACTIVE sessions so HandleTurnEnd can finalize
	// with full transcript. IDLE/ENDED sessions already have complete transcripts.
	// NOTE: This check runs AFTER TransitionAndLog updated the phase. It relies on

// TestPostCommit_ActiveSession_CommitsFileNotInFilesTouched_Condenses verifies that
// an ACTIVE session is condensed when the agent commits a file that isn't yet tracked
// in FilesTouched.
//
// This reproduces a real bug: during an active turn, the agent creates and commits a
// new file before SaveStep records it in FilesTouched. The carry-forward set from the
// previous checkpoint contains different files (e.g., from a subagent). The overlap
// check in shouldCondenseWithOverlapCheck found no intersection between the committed
// files and FilesTouched, so it returned false — leaving an orphaned checkpoint ID
// in the commit trailer with no corresponding metadata on entire/checkpoints/v1.
//
// The fix: when committedTouchedFiles is empty for an ACTIVE session, fail-open
// (return true) instead of returning false. ACTIVE sessions may have stale
// FilesTouched that doesn't include files the agent is working on mid-turn.
func TestPostCommit_ActiveSession_CommitsFileNotInFilesTouched_Condenses(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}

	// --- Create an ACTIVE session with a checkpoint ---
	sessionID := "active-mid-turn-session"
	setupSessionWithCheckpoint(t, s, repo, dir, sessionID)

	state, err := s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	state.Phase = session.PhaseActive
	// Simulate carry-forward: previous checkpoint touched test.txt, but the agent
	// is now working on a completely different file mid-turn. FilesTouched only
	// contains the carry-forward files from the last SaveStep/SaveTaskStep.
	state.FilesTouched = []string{"test.txt"}
	require.NoError(t, s.saveSessionState(context.Background(), state))

	// --- Agent creates and commits a NEW file not in FilesTouched ---
	// This is the key scenario: the agent writes new-agent-work.txt mid-turn,
	// then commits it. SaveStep hasn't run yet, so FilesTouched is stale.
	newFile := filepath.Join(dir, "new-agent-work.txt")
	require.NoError(t, os.WriteFile(newFile, []byte("agent created this mid-turn"), 0o644))

	wt, err := repo.Worktree()
	require.NoError(t, err)
	_, err = wt.Add("new-agent-work.txt")
	require.NoError(t, err)

	cpID := "ba1ba2ba3ba4"
	commitMsg := "add new agent work\n\n" + trailers.CheckpointTrailerKey + ": " + cpID + "\n"
	_, err = wt.Commit(commitMsg, &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "test@test.com", When: time.Now()},
	})
	require.NoError(t, err)

	head, err := repo.Head()
	require.NoError(t, err)
	newHead := head.Hash().String()

	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// --- Verify: ACTIVE session WAS condensed ---
	state, err = s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)

	// StepCount reset to 0 by condensation
	assert.Equal(t, 0, state.StepCount,
		"ACTIVE session should be condensed even when committed file is not in FilesTouched")

	// BaseCommit updated to new HEAD
	assert.Equal(t, newHead, state.BaseCommit,
		"ACTIVE session BaseCommit should be updated after condensation")

	// Phase stays ACTIVE
	assert.Equal(t, session.PhaseActive, state.Phase,
		"ACTIVE session should remain ACTIVE")

	// Verify entire/checkpoints/v1 exists (session was condensed)
	_, err = repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.NoError(t, err,
		"entire/checkpoints/v1 should exist — checkpoint must not be orphaned")
}

// TestPostCommit_IdleSessionEmptyFilesTouched_NotCondensed verifies that an IDLE
// session with hasNew=true but empty FilesTouched is NOT condensed into a commit.
//
// This can happen for conversation-only sessions where the transcript grew but no
// files were modified. Previously, filesOverlapWithContent was called with an empty
// list and returned false. The shouldCondenseWithOverlapCheck method must also
// return false when filesTouchedBefore is empty.
func TestPostCommit_IdleSessionEmptyFilesTouched_NotCondensed(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	s := &ManualCommitStrategy{}

	// --- Create an IDLE session with a checkpoint but no files touched ---
	idleSessionID := "idle-no-files-session"
	setupSessionWithCheckpoint(t, s, repo, dir, idleSessionID)

	idleState, err := s.loadSessionState(context.Background(), idleSessionID)
	require.NoError(t, err)
	idleState.Phase = session.PhaseIdle
	// Clear FilesTouched to simulate a conversation-only session
	idleState.FilesTouched = nil
	// CheckpointTranscriptStart=0 so sessionHasNewContent returns true
	idleState.CheckpointTranscriptStart = 0
	require.NoError(t, s.saveSessionState(context.Background(), idleState))

	idleOriginalStepCount := idleState.StepCount

	// --- Make a commit with an unrelated file ---
	wt, err := repo.Worktree()
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(dir, "other-work.txt"), []byte("other work"), 0o644))
	_, err = wt.Add("other-work.txt")

//   - Set in PostCommit when a checkpoint is condensed for an ACTIVE session
//   - Consumed in HandleTurnEnd to finalize all checkpoints with the full transcript
//   - Cleared in HandleTurnEnd after finalization completes
//   - Cleared in InitializeSession when a new prompt starts
//   - Cleared when session is reset (ResetSession deletes the state file entirely)
TurnCheckpointIDs []string `json:"turn_checkpoint_ids,omitempty"`

